// Independently authored UX intent. No expected output is generated by an engine run.
import {healthy,baseline,scenario,defect,complete,consumer,presentationInput} from './builders.mjs';
import {dependency} from '../action-plan/builders.mjs';
import {riskInputs} from '../recommendations/builders.mjs';
export function buildClientReportEntries(){const a=[];const add=(description,x,expectations={},entitlement='FULL')=>a.push({caseId:'UI-RU-'+String(a.length+1).padStart(3,'0'),description,synthetic:true,reviewStatus:'GOLDEN',input:presentationInput(x),entitlement,expectations});
add('Healthy complete profile',healthy(),{status:'Анализ сформирован'});
add('Partial profile',baseline(),{status:'Частичный расчет'});
add('Insufficient data',baseline({missingCore:true}),{status:'Недостаточно данных'});
add('Global stop',scenario({values:riskInputs['RISK-LEGAL-ENTITY-TERMINATED']}),{globalStop:true});
add('High Index distinct from constrained readiness',scenario({values:{SOURCE_STALE_COUNT:1}}),{distinct:true});
add('Low Index with adequate data',baseline({indexValue:400}),{index:400});
add('Positive Capacity',baseline({indexValue:900}),{capacity:200000});
add('Zero Capacity',scenario({debt:1000000}),{capacity:0});
add('Partial Capacity',baseline({monthCount:6}),{capacityStatus:'Частичный расчет'});
add('No principal scenario',baseline(),{noScenario:true});
for(const [description,code] of [['Negative equity','RISK-FIN-EQUITY-NON-POSITIVE'],['Working capital','RISK-FIN-WORKING-CAPITAL'],['Debt service','RISK-CF-DEBT-SERVICE-BURDEN'],['Customer concentration','RISK-CF-CUSTOMER-CONCENTRATION']])add(description,scenario({values:riskInputs[code]}),{claim:code});
add('Concentration with contract context',scenario({values:riskInputs['RISK-CF-CUSTOMER-CONCENTRATION'],contract:true}),{context:true});
add('Current overdue',scenario({values:{BKI_OVERDUE:1000,BKI_HISTORY_DAYS:30}}),{claim:'RISK-BKI-CURRENT-OVERDUE'});
add('Historical delinquency',scenario({values:riskInputs['RISK-BKI-HISTORICAL-DELINQUENCY']}),{claim:'RISK-BKI-HISTORICAL-DELINQUENCY'});
add('Data review separated from borrower',scenario({values:riskInputs['RISK-DATA-SOURCE-STALE']}),{data:true});
add('Company identity conflict',scenario({values:riskInputs['RISK-DATA-COMPANY-IDENTITY-CONFLICT']}),{data:true});
add('Source missing',scenario({values:riskInputs['RISK-DATA-SOURCE-MISSING']}),{data:true});
add('Working capital products',baseline({purpose:'WORKING_CAPITAL'}),{product:'CREDIT_LINE'});
add('Liquidity gap products',baseline({purpose:'LIQUIDITY_GAP'}),{product:'OVERDRAFT'});
add('Contract guarantee',baseline({purpose:'CONTRACT_EXECUTION',contract:true}),{product:'BANK_GUARANTEE'});
add('Factoring conditional',baseline({factoring:true}),{product:'FACTORING'});
add('Leasing',baseline({purpose:'EQUIPMENT'}),{product:'LEASING'});
add('Requested product aligned',baseline({purpose:'WORKING_CAPITAL',requested:'CREDIT_LINE'}),{aligned:true});
add('Requested product misaligned',baseline({purpose:'EQUIPMENT',requested:'OVERDRAFT'}),{misaligned:true});
add('Fit is not approval',baseline(),{fitNotApproval:true});
for(const [h,spec]of [['day7',{priority:'P1_HIGH',effort:'LOW'}],['day30',{remediability:'DIRECT'}],['day60',{effort:'HIGH'}]])add(h+' focus',complete(consumer([spec])),{focus:h});
add('Dependency visible',complete(dependency([{priority:'P1_HIGH',effort:'LOW'},{priority:'P2_MEDIUM'}])),{dependency:true});
add('Blocked by data',complete(consumer([{actionability:'BLOCKED_BY_DATA'}])),{actionStatus:'Нужны данные'});
add('Verify first',complete(consumer([{actionability:'VERIFY_FIRST'}])),{actionStatus:'Сначала проверить'});
add('Focus overflow retained',complete(consumer(Array.from({length:12},(_,i)=>({subjectKey:'subject-'+i,priority:'P1_HIGH',effort:'LOW'})))),{overflow:true});
add('Monitoring separate',complete(consumer([{actionType:'MONITOR',effort:'HIGH'}])),{monitor:true});
for(const [code,trigger]of [['VERIFY_CURRENT_OVERDUE_BALANCE','UPDATED_BKI'],['UPLOAD_COMPLETE_BANK_STATEMENT_PERIOD','NEW_BANK_STATEMENT_PERIOD'],['EXPLAIN_CURRENT_LOSS','UPDATED_FINANCIAL_STATEMENTS']])add(trigger,complete(consumer([{definitionCode:code}])),{rerun:trigger});
add('No rerun no fake CTA',complete(consumer([])),{noFakeRerun:true});
add('FREE no paid claims',baseline(),{free:true},'FREE');
add('FREE factual locked summary',healthy(),{free:true},'FREE');
add('FULL complete report',healthy(),{full:true});
add('FULL recommendations',baseline(),{recommendations:true});
add('FULL action plan',baseline(),{plan:true});
add('No duplicate main metric',healthy(),{singleIndex:true});
add('Executive factor limit',scenario({values:{FIN_EQUITY:-100,FIN_CURRENT_RATIO:.5,FIN_WORKING_CAPITAL:-100,BANK_TOP1:.8,BANK_DEBT_SERVICE_RATIO:.8,BKI_OVERDUE:1000,BKI_HISTORY_DAYS:30}}),{factorLimit:true});
add('Product overview limit',baseline(),{productLimit:true});
add('One primary CTA',baseline(),{oneCTA:true});
add('Internal codes hidden',baseline(),{noCodes:true});
add('All references valid',baseline(),{references:true});
add('Recommendation copy preserved',scenario({values:{FIN_EQUITY:-100}}),{recommendations:true});
add('Action copy preserved',baseline(),{plan:true});
add('Checkpoint not deadline',baseline(),{checkpoint:true});
add('Capacity not limit',baseline(),{capacityDisclaimer:true});
add('Print essential sections',healthy(),{print:true});
add('Print no sidebar',baseline(),{print:true});
add('Print disclaimer',baseline(),{print:true});
add('Print company and date',baseline(),{print:true});
add('Reordered input deterministic',baseline(),{reorder:true});
a.push({caseId:'UI-RU-DEFECT-001',description:'Current overdue with KNOWN historical zero: no fabricated historical band/action',synthetic:true,reviewStatus:'GOLDEN',input:presentationInput(defect()),entitlement:'FULL',expectations:{defect:true}});return a;}
